function MillHopperVibratorSpringMaker.completeMaking(m) local q=1.0+(MillHopperVibratorSpringMaker.getQualityBonus()/100); if MillHopperVibratorSpringMaker.maker then q=q+(MillHopperVibratorSpringMaker.maker.skill/140) end; q=math.min(2.5,q); MillHopperVibratorSpringMaker.productStock[m.productType]=(MillHopperVibratorSpringMaker.productStock[m.productType] or 0)+m.quantity; MillHopperVibratorSpringMaker.totalProducts=MillHopperVibratorSpringMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillHopperVibratorSpringMaker.maker then MillHopperVibratorSpringMaker.maker.itemsMade=MillHopperVibratorSpringMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillHopperVibratorSpringMaker.maker.skill=math.min(100,MillHopperVibratorSpringMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vzmet izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millhoppervibratorspring.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
